begin;
create table app.portfolio_collections(school_id uuid not null,id uuid not null default gen_random_uuid(),learner_id uuid not null,title text not null check(length(btrim(title))between 1 and 200),description text not null check(length(description)<=2000),created_at timestamptz not null default clock_timestamp(),primary key(school_id,id),foreign key(school_id,learner_id)references app.memberships(school_id,actor_id));
create unique index portfolio_collection_named_owner on app.portfolio_collections(school_id,learner_id,lower(btrim(title)));
create table app.portfolio_placement_revisions(school_id uuid not null,id uuid not null default gen_random_uuid(),item_id uuid not null,learner_id uuid not null,collection_id uuid,revision integer not null check(revision>0),position integer not null check(position between 1 and 10000),created_at timestamptz not null default clock_timestamp(),primary key(school_id,id),unique(school_id,item_id,revision),foreign key(school_id,item_id)references app.portfolio_items(school_id,id),foreign key(school_id,learner_id)references app.memberships(school_id,actor_id),foreign key(school_id,collection_id)references app.portfolio_collections(school_id,id));
create table app.portfolio_feedback_requests(school_id uuid not null,id uuid not null default gen_random_uuid(),item_id uuid not null,revision_id uuid not null,learner_id uuid not null,message text not null check(length(btrim(message))between 1 and 2000),created_at timestamptz not null default clock_timestamp(),primary key(school_id,id),unique(school_id,item_id,revision_id),foreign key(school_id,item_id)references app.portfolio_items(school_id,id),foreign key(school_id,revision_id)references app.portfolio_revisions(school_id,id),foreign key(school_id,learner_id)references app.memberships(school_id,actor_id));
create function internal.portfolio_organization_source_guard()returns trigger language plpgsql security definer set search_path=''as $$begin
 if tg_table_name='portfolio_collections'then return new;end if;
 if not exists(select 1 from app.portfolio_items item where item.school_id=new.school_id and item.id=new.item_id and item.learner_id=new.learner_id)then raise exception 'Exact portfolio learner source required'using errcode='22023';end if;
 if tg_table_name='portfolio_feedback_requests'then if not exists(select 1 from app.portfolio_revisions revision where revision.school_id=new.school_id and revision.id=new.revision_id and revision.item_id=new.item_id)then raise exception 'Exact feedback reflection source required'using errcode='22023';end if;
 elsif new.collection_id is not null and not exists(select 1 from app.portfolio_collections collection where collection.school_id=new.school_id and collection.id=new.collection_id and collection.learner_id=new.learner_id)then raise exception 'Own portfolio collection required'using errcode='22023';end if;return new;
end$$;
create trigger portfolio_organization_source before insert on app.portfolio_placement_revisions for each row execute function internal.portfolio_organization_source_guard();create trigger portfolio_request_source before insert on app.portfolio_feedback_requests for each row execute function internal.portfolio_organization_source_guard();
do $$declare tab text;begin foreach tab in array array['portfolio_collections','portfolio_placement_revisions','portfolio_feedback_requests']loop execute format('alter table app.%I enable row level security',tab);execute format('alter table app.%I force row level security',tab);execute format('revoke all on app.%I from public,anon,authenticated,service_role,cuevo_api,cuevo_worker',tab);execute format('create trigger immutable_history before update or delete on app.%I for each row execute function internal.academic_history_immutable()',tab);execute format('create trigger immutable_truncate before truncate on app.%I for each statement execute function internal.academic_history_immutable()',tab);end loop;end$$;
create function internal.organize_portfolio(command_name text,target_item uuid,payload jsonb,command_key text,fingerprint text,request_id text)returns jsonb language plpgsql security definer set search_path=''as $$declare school uuid:="authorization".school_id();actor uuid:="authorization".actor_id();item app.portfolio_items;current app.portfolio_current;revision app.portfolio_revisions;latest integer;rid uuid;reservation jsonb;receipt jsonb;begin
 if not"authorization".has_entitlement(school,'portfolio')or"authorization".current_role(school)is null or"authorization".current_role(school)<>'student'or not"authorization".can_access_school(school)then raise exception 'Own portfolio organization denied'using errcode='42501';end if;
 if payload is null or jsonb_typeof(payload)<>'object'then raise exception 'Exact portfolio organization fields required'using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(school::text||':portfolio-organize:'||actor::text,0));
 perform pg_advisory_xact_lock(hashtextextended(school::text||':school-access-mutations',0));
 if not"authorization".has_entitlement(school,'portfolio')or"authorization".current_role(school)is null or"authorization".current_role(school)is null or"authorization".current_role(school)<>'student'or not"authorization".can_access_school(school)then raise exception 'Own portfolio organization denied'using errcode='42501';end if;
 if command_name<>'collection.create'then select*into item from app.portfolio_items where school_id=school and id=target_item;if item.id is null or item.learner_id<>actor then raise exception 'Own selected evidence required'using errcode='42501';end if;perform internal.portfolio_source(item.source_model,item.evidence_id,false);select*into current from app.portfolio_current where school_id=school and item_id=item.id for update;select*into revision from app.portfolio_revisions where school_id=school and id=current.revision_id;perform internal.portfolio_source(item.source_model,item.evidence_id,false);
 end if;
 if command_name='collection.create'then if payload-'title'-'description'<>'{}'::jsonb or jsonb_typeof(payload->'title')is distinct from'string'or length(btrim(payload->>'title'))not between 1 and 200 or jsonb_typeof(payload->'description')is distinct from'string'or length(payload->>'description')>2000 then raise exception 'Named portfolio collection required'using errcode='22023';end if;
 elsif command_name='placement.create'then if jsonb_typeof(payload->'collectionId')is null or jsonb_typeof(payload->'collectionId')not in('string','null')then raise exception 'Explicit collection choice required'using errcode='22023';end if;if not(payload?&array['collectionId','expectedRevision','position'])or payload-'collectionId'-'expectedRevision'-'position'<>'{}'::jsonb or jsonb_typeof(payload->'expectedRevision')is distinct from'number'or payload->>'expectedRevision'!~'^[0-9]+$'or jsonb_typeof(payload->'position')is distinct from'number'or payload->>'position'!~'^[1-9][0-9]*$'or(payload->>'position')::integer not between 1 and 10000 or(payload->>'collectionId'is not null and not exists(select 1 from app.portfolio_collections collection where collection.school_id=school and collection.id=(payload->>'collectionId')::uuid and collection.learner_id=actor))then raise exception 'Own collection placement required'using errcode='22023';end if;
 elsif command_name='feedback.request'then
  if not(payload?&array['revisionId','expectedRevision','message','confirmRequest'])or jsonb_typeof(payload->'revisionId')is distinct from'string'or payload->>'revisionId'!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'or jsonb_typeof(payload->'expectedRevision')is distinct from'number'or payload->>'expectedRevision'!~'^[1-9][0-9]*$'then raise exception 'Exact typed feedback revision required'using errcode='22023';end if;
  if payload-'revisionId'-'expectedRevision'-'message'-'confirmRequest'<>'{}'::jsonb or payload->'confirmRequest'is distinct from'true'::jsonb or revision.id is distinct from(payload->>'revisionId')::uuid or revision.revision is distinct from(payload->>'expectedRevision')::integer or jsonb_typeof(payload->'message')is distinct from'string'or length(btrim(payload->>'message'))not between 1 and 2000 then raise exception 'Current exact reflection feedback request required'using errcode='22023';end if;
 else raise exception 'Unknown portfolio organization command'using errcode='22023';end if;
 reservation:=internal.begin_command(command_key,'portfolio.'||command_name,fingerprint);if reservation->>'state'='COMPLETED'then return reservation->'response';end if;if reservation->>'state'<>'NEW'then raise exception 'Portfolio organization in progress'using errcode='22023';end if;
 if command_name='feedback.request'and exists(select 1 from app.portfolio_reviews reviewed where reviewed.school_id=school and reviewed.item_id=item.id and reviewed.revision_id=revision.id)then raise exception 'This reflection already has teacher feedback; revise before another request'using errcode='22023';end if;
 if command_name='collection.create'then insert into app.portfolio_collections(school_id,learner_id,title,description)values(school,actor,payload->>'title',payload->>'description')returning id into rid;
 elsif command_name='placement.create'then select coalesce(max(placement.revision),0)into latest from app.portfolio_placement_revisions placement where placement.school_id=school and placement.item_id=item.id;if latest is distinct from(payload->>'expectedRevision')::integer then raise exception 'Portfolio placement revision changed'using errcode='22023';end if;insert into app.portfolio_placement_revisions(school_id,item_id,learner_id,collection_id,revision,position)values(school,item.id,actor,(payload->>'collectionId')::uuid,latest+1,(payload->>'position')::integer)returning id into rid;
 else insert into app.portfolio_feedback_requests(school_id,item_id,revision_id,learner_id,message)values(school,item.id,revision.id,actor,payload->>'message')returning id into rid;end if;
 receipt:=jsonb_build_object('id',rid,'revision',coalesce(latest+1,1));perform internal.append_audit('portfolio.'||command_name,'portfolio',rid,request_id,'succeeded','{}');perform internal.enqueue_event('portfolio.organization.changed','portfolio_organization',rid,coalesce(latest+1,1),jsonb_build_object('command',command_name),md5('portfolio-organization:'||actor::text||':'||command_name||':'||command_key));perform internal.finish_command(command_key,'portfolio.'||command_name,fingerprint,receipt);return receipt;
end$$;
create function internal.read_portfolio_organization(page_limit integer,page_cursor uuid,target_item uuid)returns jsonb language plpgsql stable security definer set search_path=''as $$declare school uuid:="authorization".school_id();actor uuid:="authorization".actor_id();item app.portfolio_items;placement app.portfolio_placement_revisions;rows jsonb;begin
 if not"authorization".has_entitlement(school,'portfolio')or"authorization".current_role(school)is null or"authorization".current_role(school)<>'student'or not"authorization".can_access_school(school)then raise exception 'Own organization read denied'using errcode='42501';end if;if page_limit is null or page_limit not between 1 and 25 then raise exception 'Bounded portfolio collections required'using errcode='22023';end if;
 if target_item is not null then select*into item from app.portfolio_items where school_id=school and id=target_item;if item.id is null or item.learner_id<>actor then raise exception 'Own organization item denied'using errcode='42501';end if;perform internal.portfolio_source(item.source_model,item.evidence_id,false);select*into placement from app.portfolio_placement_revisions where school_id=school and item_id=item.id order by revision desc limit 1;return jsonb_build_object('id',item.id,'collectionId',placement.collection_id,'position',coalesce(placement.position,1),'revision',coalesce(placement.revision,0));end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',collection.id,'title',collection.title,'description',collection.description)order by collection.id),'[]'::jsonb)into rows from(select*from app.portfolio_collections where school_id=school and learner_id=actor and(page_cursor is null or id>page_cursor)order by id limit page_limit+1)collection;return jsonb_build_object('items',case when jsonb_array_length(rows)>page_limit then rows-page_limit else rows end,'nextCursor',case when jsonb_array_length(rows)>page_limit then rows->(page_limit-1)->>'id'else null end);
end$$;
create function internal.portfolio_organization_source_allowed(target_model text,target_evidence uuid)returns boolean language plpgsql stable security definer set search_path=''as $$begin perform internal.portfolio_source(target_model,target_evidence,false);return true;exception when insufficient_privilege or invalid_parameter_value then return false;end$$;
create function internal.read_portfolio_feedback_requests(page_limit integer,page_cursor uuid)returns jsonb language plpgsql stable security definer set search_path=''as $$declare school uuid:="authorization".school_id();role_name text:="authorization".current_role("authorization".school_id());rows jsonb;begin
 if not"authorization".has_entitlement(school,'portfolio')or role_name is null or role_name not in('student','teacher','admin')or page_limit is null or page_limit not between 1 and 25 then raise exception 'Portfolio feedback request scope denied'using errcode='42501';end if;
 with candidates as materialized(select request.*from app.portfolio_feedback_requests request join app.portfolio_items item on item.school_id=request.school_id and item.id=request.item_id join app.portfolio_current current on current.school_id=item.school_id and current.item_id=item.id where request.school_id=school and current.revision_id=request.revision_id and(page_cursor is null or request.id>page_cursor)and"authorization".can_view_person(school,request.learner_id)and internal.portfolio_organization_source_allowed(item.source_model,item.evidence_id)and(role_name='student'and request.learner_id="authorization".actor_id()or role_name in('teacher','admin')and exists(select 1 from app.academic_evidence evidence join app.result_revisions result on result.school_id=evidence.school_id and result.id=evidence.result_id where item.source_model='numeric'and evidence.school_id=school and evidence.id=item.evidence_id and "authorization".can_mark_submission(school,result.submission_id) union all select 1 from app.rubric_evidence evidence join app.rubric_result_revisions result on result.school_id=evidence.school_id and result.id=evidence.result_id where item.source_model='rubric'and evidence.school_id=school and evidence.id=item.evidence_id and "authorization".can_mark_submission(school,result.submission_id)))and not exists(select 1 from app.portfolio_reviews reviewed where reviewed.school_id=request.school_id and reviewed.item_id=request.item_id and reviewed.revision_id=request.revision_id)order by request.id limit page_limit+1)
 select coalesce(jsonb_agg(jsonb_build_object('id',request.id,'itemId',request.item_id,'revisionId',request.revision_id,'learnerId',request.learner_id,'learnerName',person.display_name,'title',revision.title,'message',request.message,'state','PENDING','requestedAt',request.created_at)order by request.id),'[]'::jsonb)into rows from candidates request join app.portfolio_revisions revision on revision.school_id=request.school_id and revision.id=request.revision_id join app.people person on person.school_id=request.school_id and person.actor_id=request.learner_id;
 if octet_length(rows::text)>500000 then raise exception 'Choose a smaller feedback request page'using errcode='22023';end if;return jsonb_build_object('items',case when jsonb_array_length(rows)>page_limit then rows-page_limit else rows end,'nextCursor',case when jsonb_array_length(rows)>page_limit then rows->(page_limit-1)->>'id'else null end);
end$$;
create function internal.read_portfolio_feedback_work(target_request uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare school uuid:="authorization".school_id();request app.portfolio_feedback_requests;item app.portfolio_items;current app.portfolio_current;revision app.portfolio_revisions;source jsonb;work jsonb;begin
 if not"authorization".has_entitlement(school,'portfolio')or"authorization".current_role(school)is null or"authorization".current_role(school)not in('teacher','admin')then raise exception 'Current teacher feedback purpose required'using errcode='42501';end if;
 select*into request from app.portfolio_feedback_requests where school_id=school and id=target_request;select*into item from app.portfolio_items where school_id=school and id=request.item_id;select*into current from app.portfolio_current where school_id=school and item_id=item.id;
 if request.id is null or current.revision_id is distinct from request.revision_id then raise exception 'Current exact requested reflection required'using errcode='42501';end if;source:=internal.portfolio_source(item.source_model,item.evidence_id,false);
 if not"authorization".can_mark_submission(school,(source->>'submissionId')::uuid)then raise exception 'Current teacher source relationship required'using errcode='42501';end if;select*into revision from app.portfolio_revisions where school_id=school and id=request.revision_id and item_id=item.id;if source->>'submissionKind'='TEXT'then work:=internal.read_portfolio_source_work(item.id,request.revision_id);end if;return jsonb_build_object('requestId',request.id,'itemId',item.id,'revisionId',revision.id,'revision',revision.revision,'title',revision.title,'reflection',revision.reflection,'learnerId',item.learner_id,'learnerName',(select display_name from app.people where school_id=school and actor_id=item.learner_id),'sourceModel',item.source_model,'nativeResult',source->'nativeResult','evidenceId',item.evidence_id,'resultId',source->>'resultId','assessmentTitle',source->>'assessmentTitle','referenceTitle',source->>'referenceTitle','work',work);
end$$;
revoke execute on function internal.organize_portfolio(text,uuid,jsonb,text,text,text),internal.read_portfolio_organization(integer,uuid,uuid),internal.read_portfolio_feedback_requests(integer,uuid)from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;
grant execute on function internal.organize_portfolio(text,uuid,jsonb,text,text,text),internal.read_portfolio_organization(integer,uuid,uuid),internal.read_portfolio_feedback_requests(integer,uuid)to cuevo_api;
create function internal.read_portfolio_collection(target_collection uuid,page_limit integer,page_cursor uuid)returns jsonb language plpgsql stable security definer set search_path=''as $$declare school uuid:="authorization".school_id();actor uuid:="authorization".actor_id();collection app.portfolio_collections;entry record;source jsonb;rows jsonb:='[]';returned integer:=0;cursor_position integer;scanned integer:=0;begin
 if not"authorization".has_entitlement(school,'portfolio')or"authorization".current_role(school)is null or"authorization".current_role(school)<>'student'or not"authorization".can_access_school(school)then raise exception 'Own collection read denied'using errcode='42501';end if;if page_limit is null or page_limit not between 1 and 25 then raise exception 'Bounded collection page required'using errcode='22023';end if;
 select*into collection from app.portfolio_collections where school_id=school and id=target_collection and learner_id=actor;if not found then raise exception 'Own named collection required'using errcode='42501';end if;
 if page_cursor is not null then select placement.position into cursor_position from app.portfolio_placement_revisions placement where placement.school_id=school and placement.item_id=page_cursor and placement.collection_id=target_collection and not exists(select 1 from app.portfolio_placement_revisions newer where newer.school_id=placement.school_id and newer.item_id=placement.item_id and newer.revision>placement.revision);if cursor_position is null then raise exception 'Collection continuation changed; reopen the first page'using errcode='22023';end if;end if;
 for entry in select item.id,item.source_model,item.evidence_id,revision.id as revision_id,revision.title,revision.reflection,placement.position from app.portfolio_placement_revisions placement join app.portfolio_items item on item.school_id=placement.school_id and item.id=placement.item_id join app.portfolio_current current on current.school_id=item.school_id and current.item_id=item.id join app.portfolio_revisions revision on revision.school_id=current.school_id and revision.id=current.revision_id where placement.school_id=school and placement.collection_id=target_collection and placement.learner_id=actor and(page_cursor is null or placement.position>cursor_position or placement.position=cursor_position and item.id>page_cursor)and not exists(select 1 from app.portfolio_placement_revisions newer where newer.school_id=placement.school_id and newer.item_id=placement.item_id and newer.revision>placement.revision)order by placement.position,item.id limit 1000 loop
  scanned:=scanned+1;
  begin source:=internal.portfolio_source(entry.source_model,entry.evidence_id,false);exception when insufficient_privilege or invalid_parameter_value then continue;end;
  rows:=rows||jsonb_build_array(jsonb_build_object('id',entry.id,'revisionId',entry.revision_id,'title',entry.title,'reflection',entry.reflection,'position',entry.position));returned:=returned+1;exit when returned>page_limit;
 end loop;
 if scanned>=1000 and returned<=page_limit then raise exception 'Collection source coverage requires review before continuation'using errcode='22023';end if;
 if octet_length(rows::text)>500000 then raise exception 'Choose a smaller named collection page'using errcode='22023';end if;return jsonb_build_object('id',collection.id,'title',collection.title,'items',case when jsonb_array_length(rows)>page_limit then rows-page_limit else rows end,'nextCursor',case when jsonb_array_length(rows)>page_limit then rows->(page_limit-1)->>'id'else null end);
end$$;
revoke execute on function internal.portfolio_organization_source_guard(),internal.portfolio_organization_source_allowed(text,uuid),internal.read_portfolio_collection(uuid,integer,uuid)from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;
revoke execute on function internal.read_portfolio_feedback_work(uuid)from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;
grant execute on function internal.read_portfolio_feedback_work(uuid)to cuevo_api;
grant execute on function internal.read_portfolio_collection(uuid,integer,uuid)to cuevo_api;
do $$declare definition text;anchor text;begin
 definition:=pg_get_functiondef('internal.process_learner_event(uuid,uuid)'::regprocedure);anchor:='begin'||chr(10);if position(anchor in definition)=0 then raise exception 'Portfolio organization event dispatcher changed'using errcode='22023';end if;
 definition:=replace(definition,anchor,'begin'||chr(10)||' if exists(select 1 from internal.outbox_events event where event.id=target_event and event.type=''portfolio.organization.changed'')then select*into e from internal.outbox_events where id=target_event for update;if e.state<>''PROCESSING''or e.lease_token is distinct from current_lease or e.lease_until<=clock_timestamp()or e.entity_type<>''portfolio_organization''or not(case e.metadata->>''command''when''collection.create''then exists(select 1 from app.portfolio_collections source where source.school_id=e.school_id and source.id=e.entity_id and source.learner_id=e.actor_id and e.version=1)when''placement.create''then exists(select 1 from app.portfolio_placement_revisions source where source.school_id=e.school_id and source.id=e.entity_id and source.learner_id=e.actor_id and source.revision=e.version)when''feedback.request''then exists(select 1 from app.portfolio_feedback_requests source where source.school_id=e.school_id and source.id=e.entity_id and source.learner_id=e.actor_id and e.version=1)else false end)then raise exception ''Portfolio organization source event invalid''using errcode=''22023'';end if;insert into internal.processed_events(event_id,school_id)values(e.id,e.school_id)on conflict(event_id)do nothing;if internal.complete_outbox(e.id,current_lease)is distinct from true then raise exception ''Portfolio organization lease changed''using errcode=''22023'';end if;return jsonb_build_object(''status'',''ACKNOWLEDGED'');end if;'||chr(10));execute definition;
end$$;
commit;
